/* @autogenerated */
import { take, map } from 'rxjs';
import { BaseImportAction } from 'app/shared/toolkit/action/base-import-action';
import { ImportDefinition } from 'app/shared/toolkit/entity-import/entity-import.model';
import { ObservedDashboard } from 'app/features/observe/observed-dashboard/model/observed-dashboard.model';
import { Component, inject } from '@angular/core';
import { ObservedDashboardRepository } from 'app/features/observe/observed-dashboard/repository/observed-dashboard-repository.service';
import {
  OBSERVED_DASHBOARD_EXCEL_COLUMNS,
  OBSERVED_DASHBOARD_EXCEL_SENSITIVE,
} from 'app/features/observe/observed-dashboard/model/observed-dashboard-excel-columns';

/** Candidatos que pide cada búsqueda: el filtro puede no ser exacto y se comprueba aquí. */
const LOOKUP_LIMIT = 50;

@Component({
  selector: 'observed-dashboard-view-import-action',
  standalone: false,
  templateUrl: './observed-dashboard-view-import-action.component.html',
})
export class ObservedDashboardViewImportActionComponent extends BaseImportAction<ObservedDashboard> {
  protected readonly scope = 'observe/observed-dashboard';
  protected readonly repository = inject(ObservedDashboardRepository);

  readonly definition: ImportDefinition<ObservedDashboard> = {
    storageKey: 'observe.observed-dashboard',
    scope: this.scope,
    // Clave natural (índice único del modelo): una fila con los mismos valores actualiza el elemento
    keys: ['code'],
    columns: OBSERVED_DASHBOARD_EXCEL_COLUMNS,
    sensitive: OBSERVED_DASHBOARD_EXCEL_SENSITIVE,
    defaults: () => ({ builtin: false, sourceVariable: false, defaultRange: 'hour', refresh: 'manual' }),
    display: (values) => String(values.name ?? ''),
    target: {
      acl: () => this.repository.checkAcl(),
      find: (values) =>
        this.repository.values({ code: values.code, limit: LOOKUP_LIMIT }).pipe(
          take(1),
          map((found) => found.filter((item) => item.code === values.code)),
        ),
      add: (item) => this.repository.add(item),
      update: (item) => this.repository.update(item),
      context: this.repository.context(),
    },
  };
}
